"""Prepare evidence-backed supplementary text; new measurements remain explicitly pending."""
from common import *
import csv
import shutil

PAPER=ROOT.parents[1]/'论文初稿/20261112-CMSDA2026返修稿'
A=ROOT/'analysis/existing_evidence'

def read(name):
    with (A/name).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+
                     ['| '+' | '.join(map(str,row))+' |' for row in rows])
def main():
    cert=load(ROOT/'validation/independent_existing_evidence.json');assert cert['all_passed']
    for name,value in cert['output_hashes'].items():assert sha(A/name)==value
    target=PAPER/'supplementary/data';target.mkdir(parents=True,exist_ok=True)
    for p in A.glob('*.csv'):shutil.copyfile(p,target/p.name)
    for p in (ROOT/'analysis/metadata_inventory').glob('*.csv'):shutil.copyfile(p,target/p.name)
    for ds in ['D0m','D1','D2','D2m']:
        folder=target/ds;folder.mkdir(exist_ok=True)
        for name in ['queries.json','truth.json','tasks.json','task_truth.json']:
            if (ROOT/'inputs'/ds/name).exists():shutil.copyfile(ROOT/'inputs'/ds/name,folder/name)
    blocks=['# Supplementary methods and verified revision evidence',
      'Working revision dated November 12, 2026. This supplement contains verified results from the original study and the protocol for the reviewer-requested measurements. Formal GeoRinex and ingestion measurements are pending; their numerical results and public repository identifiers will be added after completion and independent verification.',
      '## S1 Dataset roles and absolute storage',
      'The initial parameter-training set contains BRUX, POTS, and WTZR on January 20 and 28, 2024: six sources and 907,759 records. Candidate settings were 1024, 8192, and 65536 rows under time-major or satellite-major order for W/C, and 30, 60, and 120 minutes for T/F. The family-level selection used geometric mean query time, a 3% near-optimal band, then footprint and configuration name. The selection was frozen on October 27, 2026, at 02:39:27 UTC.',
      'D0m comprises ABMF, ALGO, BRST, CEDU, KIRU, and MIZU on April 1 and July 1, 2024 (12 files, 1,658,423 records). It develops the mechanism comparisons and screens additional layouts. D1 uses ALIC, DRAO, GRAZ, HOB2, ONSA, and ZIMM on October 1–6, 2024 (36 files, 4,472,284 records), for full comparison and rule development. D2 uses FAIR, NYA2, REYK, DUBO, ALBH, and MAS1 on April 1–6, 2025 (36 files, 4,266,063 records), for independent confirmation. D2m comprises April 1 and 4 within D2 (12 files, 1,427,536 records). The initial training set, D0m, D1, and D2 have disjoint source hashes; D2m is a declared subset of D2.',
      'The labels D0m and D2m replace the ambiguous development and validation labels in the mechanism table. These controls do not use D1. The two mechanism subsets did not select the initial 8192-row or 120-minute settings. D0m results informed mechanism development and candidate screening; the independent confirmation is D2m after freezing.',
      'Table S1. Absolute stored sizes and file counts. MiB means 2^20 bytes; D/M denotes data-file and stored-metadata-file counts. The accompanying layout_storage.csv supplies exact integer byte counts for Parquet, all retained metadata, and their total. These are the original frozen layout sizes, before path sanitization for publication.',
      'Reader metadata comprise catalog.json and sources.json. layout.json retains construction settings, and boundary_plan.json additionally records the boundary intervention where applicable. metadata_breakdown.csv separates reader-metadata bytes/files from these audit files and reports both data-plus-reader and fully retained sizes. The total in Table S1 includes all of them, matching the original frozen tie-breaking rule.']
    rows=read('layout_storage.csv')
    blocks.append(table(['Dataset','Layout','Parquet MiB','Metadata MiB','Total MiB','Files D/M','Groups'],
        [[r['dataset'],r['method'].replace('Cstar','C*'),f"{int(r['parquet_bytes'])/1048576:.3f}",f"{int(r['metadata_bytes'])/1048576:.3f}",
          f"{float(r['total_mib']):.3f}",r['data_files']+'/'+r['metadata_files'],r['row_groups']] for r in rows]))
    inv=read('source_inventory.csv')
    blocks+=['The raw sources occupy 136.949 MiB as distributed CRX.gz archives and 1175.875 MiB as expanded RINEX on D1, and 132.751 MiB and 1115.748 MiB on D2, respectively. Source-level URLs, hashes and exact byte counts are in source_inventory.csv. Construction costs are measured separately under Section S6; a storage saving alone does not establish amortization.',
      '## S2 Full D1 compute-capacity results',
      'Each condition covers the same 216 requests in six paired blocks. One warm-up and three formal calls are made per request. The selected call is the median by total time, and all reported stage values come from that same call. G is the geometric mean query time, in milliseconds. B is the sum of query times, in seconds. Centers are geometric means across six blocks; ranges are block minima and maxima.',
      '![Figure S1. D1 cumulative time for all five core layouts, three output contracts, and compute-pool capacities 1, 4, 8, and 16. Points are six-block geometric centers and error bars are block minima and maxima.](../figures/D1_threads.png)',
      'Table S2. D1 full query matrix. O denotes ordered matrices, U unordered matrices, and A unordered Arrow. D1_thread_costs.csv additionally provides every block value for G, arithmetic mean A, and B.']
    rr=read('D1_thread_costs.csv');order={c:i for i,c in enumerate(CONTRACTS)}
    rr.sort(key=lambda r:(order[r['contract']],CORE.index(r['method']),int(r['cpu'])))
    blocks.append(table(['Form','Layout','CPU','G ms','B s','B block range'],
       [[['O','U','A'][order[r['contract']]],r['method'].replace('Cstar','C*'),r['cpu'],f"{float(r['G_ms']):.3f}",f"{float(r['B_s']):.3f}",
         f"{float(r['B_s_min']):.3f}–{float(r['B_s_max']):.3f}"] for r in rr]))
    blocks+=['For C with ordered matrices, capacities 1, 4, 8, and 16 give B = 9.565, 7.627, 7.756, and 7.898 s. The improvement from one to four threads is followed by slightly higher complete-query cost. The full table allows this statement to be assessed across layouts and output contracts.',
      '## S3 Recommendation and candidate threshold sensitivity',
      'The original 3% recommendation tolerance and 5% candidate thresholds remain frozen. The analyses below were specified for the revision after viewing D2 and are labeled post hoc sensitivity analyses. Each modified recommendation is constructed from D1 and evaluated on D2. No D2 result changes the primary rule.',
      'Table S3. Recommendation sensitivity over 3036 primary scenarios. Changes are relative to the frozen 3% recommendation, and excess cost is measured against the lowest D2 cost in the same scenario.']
    rr=[r for r in read('rule_sensitivity.csv') if r['grid']=='simplex']
    blocks.append(table(['Tolerance','Changed recommendations','Mean excess cost','Maximum excess cost'],
        [[f"{float(r['threshold'])*100:.0f}%",r['changed'],f"{float(r['mean_penalty'])*100:.3f}%",f"{float(r['maximum_penalty'])*100:.3f}%"] for r in rr]))
    blocks+=['![Figure S2. Mean and maximum excess costs of recommendations constructed with 1%, 3%, or 5% D1 tolerances and evaluated on the same D2 scenarios.](../figures/threshold_sensitivity.png)',
      'Additional-layout qualification compares each candidate with the lowest six-block aggregate core cost in the same predeclared query unit, using every request in that unit. Qualification requires either the specified cost reduction with improvement in at least five of six blocks, or cost within the specified near-optimal tolerance and at least the specified storage saving. The primary settings are 5%, 3%, and 5%, respectively. The arithmetic and geometric metrics and CPU/contract conditions remain separate.',
      'Table S4. One-factor-at-a-time candidate sensitivity. All seven candidates remain unqualified in every setting. candidate_sensitivity_cells.csv supplies the 40 comparison cells per setting, baseline identity, six paired ratios, same-direction count, size ratio, and both qualification tests.']
    rr=read('candidate_sensitivity_summary.csv')
    blocks.append(table(['Changed factor','Speed threshold','Near tolerance','Storage threshold','Qualified layouts'],
        [[r['axis'],f"{float(r['speed_threshold'])*100:.0f}%",f"{float(r['near_threshold'])*100:.0f}%",f"{float(r['storage_threshold'])*100:.0f}%",'None'] for r in rr]))
    blocks+=['The candidates are T_time, Tperm_time, Tperm_blocksv, C_2048, C_32768, C_full, and W_packed. C* is already a fully measured core layout. Both the empty candidate list and individual failures are retained; thresholds are not tuned to admit a layout.',
      '![Figure S3. Fixed-layout and frozen-rule excess costs on D2 under A. Each context contains 253 workload mixtures. The fixed comparator minimizes mean excess cost retrospectively on D2; the conditional rule was fixed using D1.](../figures/selection_costs.png)',
      '## S4 Exact requests and the 3036 scenarios',
      'For each dataset, let k be the zero-based station index in the order given in Section S1. Each date generates one request per station index and family. Let h = 3k hours and let u = h + 330 seconds after the source-calendar midnight. Intervals are half-open, [start, end). The fixed groups are station indices 0–2 and 3–5. Requests use physical source IDs and retain naturally empty outputs.',
      'Table S5. Exact query-family definitions. A dataset-wide code list is used wherever all codes or a code prefix is specified.']
    blocks.append(table(['Family','Sources and satellite filter','Codes','Interval'],[
        ['Q1','Station k; all satellites','All codes','[u, u + 30 min)'],
        ['Q2','Three-station group; GPS','C1C, L1C, S1C','[u, u + 15 min)'],
        ['Q3','Station k; G03, G08, G13 by k mod 3','C1C, L1C, D1C, S1C','[u, u + 2 h)'],
        ['Q4','Three-station group; all satellites','All S-prefixed codes','[h, h + 4 h)'],
        ['Q5','Station k; all satellites','All C- and L-prefixed codes','[midnight, midnight + 24 h)'],
        ['Q6','Station k; BeiDou','C2I, L2I, S2I','[u, u + 3 h)']]))
    blocks+=['GPS means the Global Positioning System; BeiDou is the Chinese navigation constellation. RINEX observation codes begin with C for pseudorange, L for carrier phase, D for Doppler, or S for signal strength. G03 is GPS satellite 03. The exact integer-microsecond intervals, source IDs, code lists, and filters are supplied in each dataset’s queries.json. truth.json supplies independently parsed row counts and fingerprints. Each full dataset has 216 requests and 30 naturally empty results. Each mechanism subset has 72 requests.',
      'Weights are all six-tuples of nonnegative multiples of 0.2 summing to one, giving 252 points, plus the equal-weight point (1/6,…,1/6). Thus 3036 = 253 weights × 2 CPU capacities × 3 output contracts × 2 metrics. The separate historical alpha grid contributes 1224 scenarios and is not included in 3036. The exact weight vectors, selected layouts, and costs are in rule_replay.csv and the frozen prediction record.',
      'For each block, the arithmetic-weighted cost is the weighted sum of family arithmetic means; the geometric-weighted cost is the exponential of the weighted sum of family log geometric means. Six block costs are combined geometrically. The near-optimal set includes costs at or below (1 + tolerance) times the minimum. Ties are resolved by stored total bytes, data-file count, and ascending fixed layout name. The implementation uses a 10^-12 absolute numerical guard for threshold equalities.',
      '## S5 Timing harness and provenance',
      'The original host uses Windows 11, a Core Ultra 7 255H with 16 logical processors, 31.49 GiB physical memory, Python 3.12.14, NumPy 2.3.5, and PyArrow 25.0.1. Parquet uses Zstandard level 3. The Arrow compute pool is set to the condition’s capacity; its I/O pool is four. OMP, OpenBLAS, MKL, and NumExpr thread environment settings are one. One request runs at a time with operating-system file caching warmed.',
      'Each configuration/block starts a fresh worker and initializes its readers and Dataset objects outside timing, including fragment metadata. Each ordinary pass begins with garbage collection. The harness performs one warm-up pass and three measured passes. Request order is shuffled using seed 627100 plus the block index. Per-request layout order is the byte ordering of SHA-256 hashes of the fixed seed, block, pass, query ID, and layout. The archived harness and per-configuration design files define the exact string serialization and full call order.',
      'Arrow scans use threads, batch_size = 131072, batch_readahead = 16, fragment_readahead = 4, cache_metadata = True, and Parquet pre_buffer = True. Normal-path timing starts before predicate/projection construction and ends after output assembly, using a monotonic high-resolution counter. Correctness checks, release of the result, and log writes occur outside timing. Task timing additionally includes adaptation, sorting, and aggregation to the final product.',
      'The completed study contains 276 configurations, 578,016 formal calls and 196,128 warm-up calls. Development data combine the original night batch, the explicitly authorized daytime batch, and the E5 tail batch. D2 records retain their night, immediate-start and extended-deadline policies. The raw run map preserves these actual sessions. Batch and block are linked, so their descriptive differences are not interpreted as an independently identified time-of-day effect.',
      'The independent checker reads raw logs, reselects the median call, and verifies each retained phase against that call. It checked 743,040 ordinary/task raw calls, 185,760 retained medians and 12,780 scenario/tolerance combinations, with 2,071,008 successful checks. The remaining 31,104 E4 calibration calls are archived separately because their balanced on/off sequences are not ordinary three-call medians. Independent relocation has reproduced these checks without requiring the original GNSS files or drive letters.',
      '## S6 Revision measurements and amortization',
      'GeoRinex 1.16.2 is used without changes to its numerical parser. The R path reads expanded RINEX. The H path reads each distributed CRX.gz archive and decompresses it on every request. Native time, constellation, and measurement filters are used. Following a timed identity scan, each matched constellation is passed through the parser’s native single-constellation path. This call organization was selected during D1 functional validation. Empty requests retain their identity-scan cost. There is no parsed-result cache.',
      'A separately timed adapter retains physical source/record identity, epoch flags, loss-of-lock indicators (LLI), signal-strength indicators (SSI), and ordered matrix organization. It does not parse observation numbers. Blank flags remain distinct from zero; missing values and negative zero are preserved. Duplicate epoch/satellite identities unsupported by the native representation are rejected. The tested D1/D2 files contain no such duplicates or unsupported non-observation events. All requests must match the independent source-parser truth before the formal campaign starts.',
      'The seven methods—five core layouts and the two GeoRinex paths—are paired on D1 and D2 under the ordered-matrix contract at CPU capacity one. Six blocks, one warm-up and three formal calls give 54,432 formal and 18,144 warm-up calls. Parse, adapter, decompression and full-return times are recorded. Formal measurements use Beijing 01:00–08:00, pausing only between complete blocks. These are post-review supplementary measurements and do not alter the original D2 choices or predictions.',
      'Construction covers 34 dataset-layout combinations: five each on D1 and D2, and twelve each on D0m and D2m, with six independent fresh builds, or 204 builds. Each dataset/block freshly decompresses source archives and prepares parsed arrays. Each layout is encoded into a new directory; old Parquet files are never copied as construction work. Decompression, shared parsing, layout encoding and mandatory metadata creation, and reader initialization are recorded separately. Closing files completes the write-time boundary; this is not a measurement of durable flush latency. Full-source correctness checks occur after timing. Rebuilt arrays and data files must reproduce their original hashes.',
      'For each block and workload, the break-even number is the ceiling of the additional preparation/build/initialization cost divided by the direct-parser arithmetic mean cost per request minus the layout arithmetic mean cost per request. Nonpositive differences have no finite break-even point. The R numerator excludes decompression; the H numerator includes it. The complete preparation cost is counted for a standalone layout even when preparation was shared during measurement. Equal weights, the six families and all 253 mixtures are reported, including all six block values and the ratio of across-block arithmetic-mean costs. Formal numerical results remain pending.',
      '## S7 Reproduction and availability',
      'The local release candidate contains locked dependencies, builders, readers, the baseline adapter, historical frozen harness versions, exact requests, independent truth summaries, original timing logs, processed tables and frozen predictions. The portable fast entry replays the 3036 main scenarios and separate historical grid. A second entry downloads original sources by URL, checks hashes, rebuilds layouts in a new output directory and verifies all three output contracts and complete tasks. Raw GNSS files are obtained from their original public archive rather than redistributed.',
      'The fast path is reproduce.py analyze followed by independent_review.py; both accept an external analysis output directory. The complete path uses reproduce.py download, rebuild and benchmark with explicit source and output directories. plot_results.py renders the thread and sensitivity figures from the supplied CSV files. The revised measurement analyzer accepts only a complete, audited campaign and has an independent recomputation entry.',
      'GitHub and Zenodo publication has not occurred at this working-draft stage. Public links and a DOI will be inserted only after the release is uploaded and checked. An anonymous review copy will omit author-linked archive pages, names, email, and local identity metadata. The AI assistance statement remains: “AI tools assisted with writing portions of the code.”']
    source=PAPER/'source/supplementary_working.md';source.write_text('\n\n'.join(blocks)+'\n',encoding='utf-8')
    dump(PAPER/'checks/supplement_evidence.json',dict(status='working_pending_formal_baseline_build_and_publication',
        source_sha256=sha(source),verified_tables=cert['output_hashes'],public_urls_added=False))
    print('Prepared evidence-backed working supplement and machine-readable tables.')

if __name__=='__main__':main()
